package v1

import (
	"bytes"
	"context"
	"io"
	"reflect"

	"github.com/ClessLi/component-base/pkg/errors"
	"google.golang.org/grpc"
)

// MsgExtractor extracts the payload bytes from a streamed protobuf message.
// It is the client-side counterpart of the server framework's MsgAssembler.
type MsgExtractor[ProtoMsg any] func(msg ProtoMsg) []byte

// StreamOpener opens a server-streaming RPC and returns the client stream.
// The concrete opener is generated by the protobuf client (e.g. DemoClient.Download),
// whose stream type embeds grpc.ClientStream.
type StreamOpener[REQ any] func(ctx context.Context, req REQ) (grpc.ClientStream, error)

// StreamRecvMsg receives all messages from a server stream and concatenates their
// extracted payloads into a complete byte slice. It hides the chunked transport from
// the caller: io.EOF terminates the loop and returns the aggregated data.
// ProtoMsg must be a pointer to a protobuf message (e.g. *pbv1.Chunk).
func StreamRecvMsg[ProtoMsg any](stream grpc.ClientStream, extractor MsgExtractor[ProtoMsg]) ([]byte, error) {
	if extractor == nil {
		return nil, errors.New("message extractor must not be nil")
	}
	msgType := reflect.TypeOf((*ProtoMsg)(nil)).Elem()
	if msgType.Kind() != reflect.Ptr {
		return nil, errors.Errorf("ProtoMsg must be a pointer type, got %s", msgType.String())
	}

	var buf bytes.Buffer
	for {
		// Stop early if the stream context is done (client cancelled or deadline exceeded).
		if err := stream.Context().Err(); err != nil {
			return nil, err
		}

		msg := reflect.New(msgType.Elem()).Interface()
		if err := stream.RecvMsg(msg); err != nil {
			if errors.Is(err, io.EOF) {
				return buf.Bytes(), nil
			}
			return nil, err
		}

		typed, ok := msg.(ProtoMsg)
		if !ok {
			return nil, errors.Errorf("stream message type %T is not ProtoMsg", msg)
		}
		buf.Write(extractor(typed))
	}
}

